package main

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"time"
)

type Leg struct {
	Hub  string `json:"hub"`
	Mins int    `json:"mins"`
}

func main() {
	dec := json.NewDecoder(strings.NewReader(`{"hub":"Oslo","mins":40} {"hub":"Rome","mins":95} {"hub":"Lima","mins":30}`))
	clock := time.Date(2026, time.July, 9, 8, 0, 0, 0, time.UTC)
	for {
		var leg Leg
		if err := dec.Decode(&leg); err == io.EOF {
			break
		} else if err != nil {
			fmt.Println("error:", err)
			return
		}
		took := time.Duration(leg.Mins) * time.Minute
		clock = clock.Add(took)
		fmt.Println(leg.Hub, took, clock.Format("15:04"))
	}
}

