package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
)

type Scan struct {
	ID  int    `json:"id"`
	Hub string `json:"hub"`
}

func main() {
	feed := strings.NewReader(`{"id": 1, "hub": "Oslo"}
{"id": 1, "hub": "Rome"}
{"id": 2, "hub": "Lima"}`)
	dec := json.NewDecoder(feed)
	for {
		var s Scan
		err := dec.Decode(&s)
		if err == io.EOF {
			break
		}
		if err != nil {
			fmt.Println("error:", err)
			return
		}
		fmt.Printf("parcel %d reached %s\n", s.ID, s.Hub)
	}
	enc := json.NewEncoder(os.Stdout)
	enc.Encode(Scan{ID: 3, Hub: "Pune"})
}

